CREATE TABLE `User` (`id` VARCHAR(36) NOT NULL,`name` VARCHAR(120) NOT NULL,`username` VARCHAR(80) NOT NULL,`passwordHash` VARCHAR(255) NOT NULL,`role` ENUM('ADMIN','READER') NOT NULL DEFAULT 'READER',`active` BOOLEAN NOT NULL DEFAULT true,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL,UNIQUE INDEX `User_username_key`(`username`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Session` (`id` VARCHAR(36) NOT NULL,`userId` VARCHAR(36) NOT NULL,`expiresAt` DATETIME(3) NOT NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),INDEX `Session_userId_idx`(`userId`),INDEX `Session_expiresAt_idx`(`expiresAt`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Series` (`id` VARCHAR(36) NOT NULL,`title` VARCHAR(160) NOT NULL,`description` TEXT NOT NULL,`genre` VARCHAR(120) NOT NULL,`status` ENUM('DRAFT','PUBLISHED') NOT NULL DEFAULT 'DRAFT',`sortOrder` INTEGER NOT NULL DEFAULT 0,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL,INDEX `Series_status_sortOrder_idx`(`status`,`sortOrder`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Book` (`id` VARCHAR(36) NOT NULL,`seriesId` VARCHAR(36) NOT NULL,`title` VARCHAR(160) NOT NULL,`subtitle` VARCHAR(200) NULL,`description` TEXT NOT NULL,`volumeNumber` INTEGER NOT NULL,`sortOrder` INTEGER NOT NULL DEFAULT 0,`status` ENUM('DRAFT','PUBLISHED') NOT NULL DEFAULT 'DRAFT',`coverPath` VARCHAR(255) NULL,`coverMimeType` VARCHAR(80) NULL,`coverOriginalName` VARCHAR(255) NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL,UNIQUE INDEX `Book_seriesId_volumeNumber_key`(`seriesId`,`volumeNumber`),INDEX `Book_seriesId_status_sortOrder_idx`(`seriesId`,`status`,`sortOrder`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Chapter` (`id` VARCHAR(36) NOT NULL,`bookId` VARCHAR(36) NOT NULL,`title` VARCHAR(200) NOT NULL,`content` LONGTEXT NOT NULL,`sortOrder` INTEGER NOT NULL,`status` ENUM('DRAFT','PUBLISHED') NOT NULL DEFAULT 'DRAFT',`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL,UNIQUE INDEX `Chapter_bookId_sortOrder_key`(`bookId`,`sortOrder`),INDEX `Chapter_bookId_status_sortOrder_idx`(`bookId`,`status`,`sortOrder`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Bookmark` (`userId` VARCHAR(36) NOT NULL,`bookId` VARCHAR(36) NOT NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY (`userId`,`bookId`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `ReadingProgress` (`userId` VARCHAR(36) NOT NULL,`bookId` VARCHAR(36) NOT NULL,`chapterId` VARCHAR(36) NOT NULL,`updatedAt` DATETIME(3) NOT NULL,INDEX `ReadingProgress_chapterId_idx`(`chapterId`),PRIMARY KEY (`userId`,`bookId`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
ALTER TABLE `Session` ADD CONSTRAINT `Session_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `Book` ADD CONSTRAINT `Book_seriesId_fkey` FOREIGN KEY (`seriesId`) REFERENCES `Series`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `Chapter` ADD CONSTRAINT `Chapter_bookId_fkey` FOREIGN KEY (`bookId`) REFERENCES `Book`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `Bookmark` ADD CONSTRAINT `Bookmark_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `Bookmark` ADD CONSTRAINT `Bookmark_bookId_fkey` FOREIGN KEY (`bookId`) REFERENCES `Book`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `ReadingProgress` ADD CONSTRAINT `ReadingProgress_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `ReadingProgress` ADD CONSTRAINT `ReadingProgress_bookId_fkey` FOREIGN KEY (`bookId`) REFERENCES `Book`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `ReadingProgress` ADD CONSTRAINT `ReadingProgress_chapterId_fkey` FOREIGN KEY (`chapterId`) REFERENCES `Chapter`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
